import json, os, queue, shutil, subprocess, threading
from pathlib import Path
config=json.loads(Path('.mcp.json').read_text())['mcpServers']['umbraco']
env=os.environ.copy()
env.update(config['env'])
env['UMBRACO_BASE_URL']=os.environ.get('UMBRACO_MCP_URL') or 'https://localhost:44317'
exe=shutil.which('npx.cmd') or shutil.which('npx')
process=subprocess.Popen([exe,*config['args']],stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,bufsize=1,env=env)
q=queue.Queue()
def pump(stream,kind):
    for line in stream:
        q.put((kind,line.strip()))
threading.Thread(target=pump,args=(process.stdout,'stdout'),daemon=True).start()
threading.Thread(target=pump,args=(process.stderr,'stderr'),daemon=True).start()
def send(obj):
    process.stdin.write(json.dumps(obj)+'\\n')
    process.stdin.flush()
def reply(expected,timeout=40):
    import time
    end=time.monotonic()+timeout
    while time.monotonic()<end:
        try: kind,line=q.get(timeout=min(1,end-time.monotonic()))
        except queue.Empty:
            if process.poll() is not None: raise RuntimeError('MCP process exited '+str(process.returncode))
            continue
        if kind=='stderr':
            print('SERVER:',line[:300])
            continue
        try: obj=json.loads(line)
        except json.JSONDecodeError:
            print('STDOUT:',line[:300]); continue
        if obj.get('id')==expected: return obj
    raise TimeoutError('No MCP reply')
try:
    send({'jsonrpc':'2.0','id':1,'method':'initialize','params':{'protocolVersion':'2025-03-26','capabilities':{},'clientInfo':{'name':'umbraco-bench-connectivity-check','version':'1.0'}}})
    init=reply(1)
    print('INITIALIZE:',json.dumps(init))
    if 'error' in init: raise RuntimeError('Initialization failed')
    send({'jsonrpc':'2.0','method':'notifications/initialized'})
    send({'jsonrpc':'2.0','id':2,'method':'tools/list','params':{}})
    listed=reply(2)
    if 'error' in listed: print('LIST_ERROR:',json.dumps(listed['error']))
    else:
        tools=listed.get('result',{}).get('tools',[])
        print('TOOL_COUNT:',len(tools))
        print('READ_TOOLS:',json.dumps([{'name':t['name'],'schema':t.get('inputSchema')} for t in tools if t['name'].startswith(('get-','list-'))][:15]))
finally:
    process.terminate()
    try: process.wait(timeout=3)
    except subprocess.TimeoutExpired: process.kill()
'@ | python -"

