import json
import os
import queue
import shutil
import subprocess
import sys
import threading
import time
from pathlib import Path

config = json.loads(Path('.mcp.json').read_text())['mcpServers']['umbraco']
env = os.environ.copy()
env.update(config['env'])
env['UMBRACO_BASE_URL'] = os.environ.get('UMBRACO_MCP_URL') or 'https://localhost:44317'
process = subprocess.Popen(
    [shutil.which('npx.cmd') or shutil.which('npx'), *config['args']],
    stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL,
    text=True, bufsize=1, env=env,
)
responses = queue.Queue()

def collect():
    for line in process.stdout:
        try:
            responses.put(json.loads(line))
        except json.JSONDecodeError:
            pass

threading.Thread(target=collect, daemon=True).start()

def rpc(number, method, params=None):
    process.stdin.write(json.dumps({'jsonrpc': '2.0', 'id': number, 'method': method, 'params': params or {}}) + '\n')
    process.stdin.flush()
    deadline = time.monotonic() + 60
    while time.monotonic() < deadline:
        try:
            response = responses.get(timeout=1)
        except queue.Empty:
            if process.poll() is not None:
                raise RuntimeError(f'MCP process exited: {process.returncode}')
            continue
        if response.get('id') == number:
            return response
    raise TimeoutError(method)

try:
    initialized = rpc(1, 'initialize', {
        'protocolVersion': '2025-03-26', 'capabilities': {},
        'clientInfo': {'name': 'umbraco-bench-blog-demo', 'version': '1.0'},
    })
    if 'error' in initialized:
        raise RuntimeError(initialized['error'])
    process.stdin.write(json.dumps({'jsonrpc': '2.0', 'method': 'notifications/initialized'}) + '\n')
    process.stdin.flush()
    if len(sys.argv) > 1 and sys.argv[1] == 'schema':
        names = sys.argv[2:]
        tools = rpc(2, 'tools/list')['result']['tools']
        for tool in tools:
            if any(part in tool['name'] for part in names):
                print(json.dumps({'name': tool['name'], 'inputSchema': tool.get('inputSchema')}, ensure_ascii=False))
    else:
        calls = json.load(sys.stdin)
        for number, call in enumerate(calls, 2):
            result = rpc(number, 'tools/call', {'name': call['name'], 'arguments': call.get('arguments', {})})
            result = result.get('result', result)
            print(json.dumps({'name': call['name'], 'result': result.get('structuredContent', result)}, ensure_ascii=False))
finally:
    process.terminate()
    try:
        process.wait(timeout=3)
    except subprocess.TimeoutExpired:
        process.kill()

