@using Umbraco.Cms.Core.Models.Blocks
@using Umbraco.Bench.Umbraco.Models
@using Umbraco.Bench.Umbraco.Models.Blocks
@inherits UmbracoViewPage<BlockGridItem<PostFeedBlock>>
@{
    var posts = Umbraco.AssignedContentItem?.Children<BlogPostPage>() ?? Enumerable.Empty<BlogPostPage>();
    var cards = posts.Select(post =>
    {
        var hero = post.Blocks?.FirstOrDefault()?.Content as HeroBlock;
        return new PostCardModel
        {
            Title = hero?.Heading ?? post.Name,
            Kicker = hero?.Kicker ?? "Story",
            Summary = hero?.Summary ?? "",
            ImageUrl = hero?.Image?.GetCropUrl(width: 900, height: 600),
            Url = post.Url()
        };
    }).ToArray();
    var model = new PostFeedModel
    {
        Heading = Model.Content.Heading ?? "",
        Intro = Model.Content.Intro ?? "",
        Posts = cards
    };
}
@await Component.InvokeAsync("PostFeed", new { model })

